// JSON → SQL Generator
// Generates INSERT statements from JSON array

var jsonInput = input.get("jsonInput");
var tableName = input.get("tableName") || "MyTable";
var batchSize = parseInt(input.get("batchSize") || "1");
var includeColumns = input.get("includeColumns") || "";
var excludeColumns = input.get("excludeColumns") || "";

if (!jsonInput || jsonInput.trim() === "") {
    log.error("JSON input is required");
    output.set("HasErrors", true);
    output.set("ErrorMessage", "JSON input is required");
    output.set("Sql", "");
    tags.trigger("error");
} else {
    try {
        var data = json.parse(jsonInput);
        if (!Array.isArray(data)) {
            data = [data]; // Wrap single object in array
        }
        if (data.length === 0) {
            throw new Error("JSON array is empty");
        }

        // Parse column filters
        var includeList = includeColumns ? includeColumns.split(',').map(function(s) { return s.trim(); }) : null;
        var excludeList = excludeColumns ? excludeColumns.split(',').map(function(s) { return s.trim(); }) : [];

        // Get columns from first object
        var allColumns = Object.keys(data[0]);
        var columns = allColumns.filter(function(col) {
            if (includeList && includeList.indexOf(col) === -1) return false;
            if (excludeList.indexOf(col) >= 0) return false;
            return true;
        });

        if (columns.length === 0) {
            throw new Error("No columns to insert after filtering");
        }

        function escapeValue(val) {
            if (val === null || val === undefined) return "NULL";
            if (typeof val === "number") return String(val);
            if (typeof val === "boolean") return val ? "1" : "0";
            if (typeof val === "object") val = json.stringify(val);
            // Escape single quotes
            return "'" + String(val).replace(/'/g, "''") + "'";
        }

        var statements = [];
        var columnList = "[" + columns.join("],[")+"]";

        if (batchSize > 1) {
            // Batch insert mode
            for (var i = 0; i < data.length; i += batchSize) {
                var batch = data.slice(i, Math.min(i + batchSize, data.length));
                var values = [];
                for (var j = 0; j < batch.length; j++) {
                    var row = batch[j];
                    var rowVals = [];
                    for (var k = 0; k < columns.length; k++) {
                        rowVals.push(escapeValue(row[columns[k]]));
                    }
                    values.push("(" + rowVals.join(",") + ")");
                }
                statements.push("INSERT INTO [" + tableName + "] (" + columnList + ") VALUES\n" + values.join(",\n") + ";");
            }
        } else {
            // Single row inserts
            for (var i = 0; i < data.length; i++) {
                var row = data[i];
                var vals = [];
                for (var k = 0; k < columns.length; k++) {
                    vals.push(escapeValue(row[columns[k]]));
                }
                statements.push("INSERT INTO [" + tableName + "] (" + columnList + ") VALUES (" + vals.join(",") + ");");
            }
        }

        var sql = statements.join("\n\n");

        output.set("Sql", sql);
        output.set("RowCount", data.length);
        output.set("ColumnCount", columns.length);
        output.set("Columns", json.stringify(columns));
        output.set("StatementCount", statements.length);
        output.set("HasErrors", false);
        output.set("ErrorMessage", "");

        log.info("Generated " + statements.length + " INSERT statements for " + data.length + " rows");
        tags.trigger("success");

    } catch (ex) {
        log.error("SQL generation failed: " + ex.message);
        output.set("HasErrors", true);
        output.set("ErrorMessage", ex.message);
        output.set("Sql", "");
        tags.trigger("error");
    }
}
